var IMG='img/';
var CATN={verloving:'Verlovingsringen',dr:'Ringen',tr:'Trouwringen',hr:'Herenringen',ar:'Armbanden',ke:'Kettingen',ha:'Hangers',oo:'Oorringen',br:'Broches',as:'Asjuwelen'};
var CATN_EN={verloving:'Engagement rings',dr:'Rings',tr:'Wedding rings',hr:"Men's rings",ar:'Bracelets',ke:'Necklaces',ha:'Pendants',oo:'Earrings',br:'Brooches',as:'Ash jewellery'};
var VOCAB_EN={'wit goud':'white gold','geel goud':'yellow gold','rood goud':'red gold','rosé goud':'rosé gold','zwart goud':'black gold','iced goud':'iced gold','goud':'gold','wit en geel goud':'white and yellow gold','wit en rood goud':'white and red gold','wit en rosé goud':'white and rosé gold','platina':'platinum','diamant':'diamond','saffier':'sapphire','parel':'pearl','email':'enamel','briljant':'brilliant','princess':'princess','ovaal':'oval','peer':'pear','cushion':'cushion','carré':'square','markies':'marquise'};
function trGold(s){
  if(!s)return s;
  var out=s.replace('18 kt','18ct');
  var keys=Object.keys(VOCAB_EN).filter(function(k){return /goud|platina/.test(k);}).sort(function(a,b){return b.length-a.length;});
  keys.forEach(function(k){if(out.indexOf(k)>=0)out=out.replace(k,VOCAB_EN[k]);});
  return out;
}
function trWord(s){if(!s)return s;return s.split(', ').map(function(w){return VOCAB_EN[w]||w;}).join(', ');}
var SPEC_LBL={nl:{l:'Legering',s:'Edelsteen',v:'Vorm',a:'Artikelcode'},en:{l:'Alloy',s:'Gemstone',v:'Shape',a:'Item code'}};
var lang='nl';
var byId={};PRODUCTS.forEach(function(p){byId[p.i]=p;});
var state={g:'alle',sort:'name',shown:30,q:'',price:'',stone:''};
var grid=document.getElementById('grid'),count=document.getElementById('count'),moreBtn=document.getElementById('moreBtn');
function fmt(n){return '€ '+n.toLocaleString('nl-BE',{minimumFractionDigits:0,maximumFractionDigits:0});}
function ls(k,d){try{return JSON.parse(localStorage.getItem(k))||d;}catch(e){return d;}}
function lsSet(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){}}
var wish=ls('rj_wish',[]),recent=ls('rj_recent',[]);
function list(){
  var q=state.q.toLowerCase();
  var l=PRODUCTS.filter(function(p){
    if(state.g!=='alle'&&p.g!==state.g)return false;
    if(q&&p.n.toLowerCase().indexOf(q)<0&&p.a.indexOf(q)<0)return false;
    if(state.stone&&p.s.indexOf(state.stone)<0)return false;
    if(state.price){var r=state.price.split('-');if(p.p<+r[0])return false;if(r[1]&&p.p>=+r[1])return false;}
    return true;
  });
  if(state.sort==='asc')l.sort(function(a,b){return a.p-b.p;});
  else if(state.sort==='desc')l.sort(function(a,b){return b.p-a.p;});
  else l.sort(function(a,b){return a.n.localeCompare(b.n,'nl');});
  return l;
}
function cardHTML(p){
  var on=wish.indexOf(p.i)>=0;
  var l=lang==='en'?trGold(p.l):p.l, s=lang==='en'?trWord(p.s):p.s;
  var vanaf=lang==='en'?'from ':'vanaf ', incl=lang==='en'?'incl. VAT':'incl. btw', det=lang==='en'?'View details ›':'Bekijk details ›';
  return '<article class="card" data-id="'+p.i+'"><div class="ph"><img src="'+IMG+p.i+'.jpg" alt="'+p.n+'" loading="lazy"><button class="fav'+(on?' on':'')+'" data-fav="'+p.i+'" aria-label="Bewaren">'+(on?'♥':'♡')+'</button></div><div class="body"><div class="name">'+p.n+'</div><div class="meta">'+l+(s?' · '+s:'')+'</div><div class="price">'+vanaf+fmt(p.p)+'<small>'+incl+'</small></div><div class="quick">'+det+'</div></div></article>';
}
var current=[];
function render(){
  var l=list();current=l;
  var empty=lang==='en'?'No models found. Try a different word or clear the filters — or come by: our archive holds over 7000 designs.':'Geen modellen gevonden. Probeer een ander woord of wis de filters — of kom langs: in ons archief zitten ruim 7000 ontwerpen.';
  grid.innerHTML=l.length?l.slice(0,state.shown).map(cardHTML).join(''):'<p class="empty">'+empty+'</p>';
  count.textContent=Math.min(state.shown,l.length)+(lang==='en'?' of '+l.length+' models':' van '+l.length+' modellen');
  moreBtn.style.display=l.length>state.shown?'inline-block':'none';
}
document.querySelectorAll('.tab').forEach(function(b){b.addEventListener('click',function(){setCat(b.dataset.g);});});
function setCat(g){document.querySelectorAll('.tab').forEach(function(x){x.classList.toggle('on',x.dataset.g===g);});state.g=g;state.shown=30;render();}
document.querySelector('.tab').classList.add('on');
document.getElementById('sort').addEventListener('change',function(e){state.sort=e.target.value;render();});
document.getElementById('price').addEventListener('change',function(e){state.price=e.target.value;state.shown=30;render();});
document.getElementById('stone').addEventListener('change',function(e){state.stone=e.target.value;state.shown=30;render();});
var qEl=document.getElementById('q');qEl.addEventListener('input',function(e){state.q=e.target.value.trim();state.shown=30;render();});
document.getElementById('reset').addEventListener('click',function(){state.q='';state.price='';state.stone='';qEl.value='';document.getElementById('price').value='';document.getElementById('stone').value='';setCat('alle');});
moreBtn.addEventListener('click',function(){state.shown+=30;render();});
document.querySelectorAll('.chip').forEach(function(c){c.addEventListener('click',function(){
  document.querySelectorAll('.chip').forEach(function(x){x.classList.remove('on');});c.classList.add('on');
  setCat(c.dataset.go);document.getElementById('catalogus').scrollIntoView({behavior:'smooth'});
});});
document.addEventListener('click',function(e){
  var f=e.target.closest('[data-fav]');if(f){e.stopPropagation();toggleWish(f.dataset.fav);return;}
  var c=e.target.closest('.card,.rel,.wl');if(c&&c.dataset.id){openProduct(c.dataset.id);}
});

/* wishlist */
function toggleWish(id){var i=wish.indexOf(id);if(i>=0)wish.splice(i,1);else wish.push(id);lsSet('rj_wish',wish);syncWish();}
function syncWish(){
  document.getElementById('wishCount').textContent=wish.length;
  document.querySelectorAll('[data-fav]').forEach(function(b){var on=wish.indexOf(b.dataset.fav)>=0;b.classList.toggle('on',on);b.textContent=on?'♥':'♡';});
  var h=document.getElementById('pdWish');if(pdId){var on=wish.indexOf(pdId)>=0;h.classList.toggle('on',on);h.innerHTML='<span>'+(on?(lang==='en'?'♥ Saved':'♥ Bewaard'):(lang==='en'?'♡ Save':'♡ Bewaren'))+'</span>';}
  var wl=document.getElementById('wishList');
  var vanaf=lang==='en'?'from ':'vanaf ', emptyW=lang==='en'?"Nothing saved yet. Tap the heart on a jewel.":'Nog niets bewaard. Tik op het hartje bij een juweel.';
  wl.innerHTML=wish.length?wish.map(function(id){var p=byId[id];return '<div class="wl" data-id="'+id+'"><div class="ph"><img src="'+IMG+id+'.jpg" alt=""></div><p>'+p.n+'<b>'+vanaf+fmt(p.p)+'</b></p><button data-fav="'+id+'" aria-label="Verwijderen">×</button></div>';}).join(''):'<p class="empty">'+emptyW+'</p>';
}
document.getElementById('wishBtn').addEventListener('click',function(){open('wd');});
document.getElementById('wishClear').addEventListener('click',function(){wish=[];lsSet('rj_wish',wish);syncWish();});
document.getElementById('wishAppt').addEventListener('click',function(){openForm('Afspraak',null,true);});

/* drawers */
var openId=null;
function open(id){document.body.classList.add('open');document.getElementById(id).classList.add('show');document.getElementById(id).setAttribute('aria-hidden','false');openId=id;}
function closeAll(){['pd','fd','wd','cd'].forEach(function(id){var d=document.getElementById(id);d.classList.remove('show');d.setAttribute('aria-hidden','true');});document.body.classList.remove('open');openId=null;if(location.hash.indexOf('#p=')===0)history.replaceState(null,'',location.pathname+'#catalogus');}
document.getElementById('scrim').addEventListener('click',closeAll);
['pdClose','fdClose','wdClose'].forEach(function(id){document.getElementById(id).addEventListener('click',function(){if(id==='fdClose'&&pdId){document.getElementById('fd').classList.remove('show');open('pd');}else closeAll();});});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeAll();if(openId==='pd'){if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1);}});

/* product detail */
var pdId=null,color='';
function openProduct(id){
  var p=byId[id];if(!p)return;pdId=id;color='';
  document.getElementById('pdImg').src=IMG+id+'.jpg';document.getElementById('pdImg').alt=p.n;
  document.getElementById('pdName').textContent=p.n;
  document.getElementById('pdCrumb').textContent=(lang==='en'?CATN_EN[p.g]:CATN[p.g])+' · '+p.a;
  var L=SPEC_LBL[lang];
  var sp=[[L.l,lang==='en'?trGold(p.l):p.l]];if(p.s)sp.push([L.s,lang==='en'?trWord(p.s):p.s]);if(p.v)sp.push([L.v,lang==='en'?(VOCAB_EN[p.v]||p.v):p.v]);sp.push([L.a,p.a]);
  document.getElementById('pdSpecs').innerHTML=sp.map(function(r){return '<dt>'+r[0]+'</dt><dd>'+r[1]+'</dd>';}).join('');
  document.getElementById('pdPrice').textContent=fmt(p.p);
  document.querySelectorAll('#swatches button').forEach(function(b){b.classList.remove('on');});
  document.getElementById('chosen').textContent=lang==='en'?('Shown in '+trGold(p.l.replace('18 kt ',''))+'. Choose your preference.'):('Getoond in '+p.l.replace('18 kt ','')+'. Kies uw voorkeur.');
  var rel=PRODUCTS.filter(function(x){return x.g===p.g&&x.i!==id;}).sort(function(a,b){return Math.abs(a.p-p.p)-Math.abs(b.p-p.p);}).slice(0,4);
  var vanaf=lang==='en'?'from ':'vanaf ';
  document.getElementById('pdRel').innerHTML=rel.map(function(x){return '<div class="rel" data-id="'+x.i+'"><div class="ph"><img src="'+IMG+x.i+'.jpg" alt="" loading="lazy"></div><p>'+x.n+'<b>'+vanaf+fmt(x.p)+'</b></p></div>';}).join('');
  var idx=current.map(function(x){return x.i;}).indexOf(id);
  document.getElementById('pdPrev').disabled=idx<=0;document.getElementById('pdNext').disabled=idx<0||idx>=current.length-1;
  document.getElementById('pd').scrollTop=0;
  recent=[id].concat(recent.filter(function(x){return x!==id;})).slice(0,6);lsSet('rj_recent',recent);renderRecent();
  history.replaceState(null,'',location.pathname+'#p='+id);
  syncWish();open('pd');
}
function step(d){var ids=current.map(function(x){return x.i;}),i=ids.indexOf(pdId)+d;if(i>=0&&i<ids.length)openProduct(ids[i]);}
document.getElementById('pdPrev').addEventListener('click',function(){step(-1);});
document.getElementById('pdNext').addEventListener('click',function(){step(1);});
document.querySelectorAll('#swatches button').forEach(function(b){b.addEventListener('click',function(){
  document.querySelectorAll('#swatches button').forEach(function(x){x.classList.remove('on');});b.classList.add('on');color=b.dataset.c;
  document.getElementById('chosen').textContent=lang==='en'?('Your choice: '+(VOCAB_EN[color]||color)+'. We make this model in that finish for you.'):('Uw keuze: '+color+'. Wij maken dit model in die uitvoering voor u.');
});});
document.getElementById('pdWish').addEventListener('click',function(){toggleWish(pdId);});
document.getElementById('pdZoom').addEventListener('click',function(){document.getElementById('lbImg').src=IMG+pdId+'.jpg';document.getElementById('lb').classList.add('show');});
document.getElementById('lbClose').addEventListener('click',function(){document.getElementById('lb').classList.remove('show');});
document.getElementById('lb').addEventListener('click',function(e){if(e.target.id==='lb')e.currentTarget.classList.remove('show');});
document.getElementById('pdAppt').addEventListener('click',function(){openForm('Afspraak',byId[pdId],false);});
document.getElementById('pdAsk').addEventListener('click',function(){openForm('Vraag',byId[pdId],false);});

/* forms */
function openForm(kind,p,fromWish){
  var appt=kind==='Afspraak';
  document.getElementById('fdTitle').textContent=lang==='en'?(appt?'Make an appointment':'Ask your question'):(appt?'Maak een afspraak':'Stel uw vraag');
  document.getElementById('fdWhen').style.display=appt?'block':'none';
  document.getElementById('fdMsgLbl').textContent=lang==='en'?(appt?'What can we lay out for you?':'Your question'):(appt?'Wat mogen we voor u klaarleggen?':'Uw vraag');
  var ab='';
  if(fromWish)ab=lang==='en'?('About your wishlist with '+wish.length+' jewel'+(wish.length===1?'':'s')+'. We will lay them out in the showroom.'):('Over uw verlanglijst met '+wish.length+' juwe'+(wish.length===1?'el':'len')+'. We leggen ze klaar in de toonzaal.');
  else if(p)ab=lang==='en'?('About: '+p.n+(color?' in '+(VOCAB_EN[color]||color):'')+' (item '+p.a+').'):('Over: '+p.n+(color?' in '+color:'')+' (art. '+p.a+').');
  document.getElementById('fdAbout').textContent=ab;
  document.getElementById('fdOk').hidden=true;
  document.getElementById('pd').classList.remove('show');document.getElementById('wd').classList.remove('show');
  open('fd');
}
document.querySelectorAll('.chips button').forEach(function(b){b.addEventListener('click',function(){var sib=b.parentNode.querySelectorAll('button');sib.forEach(function(x){x.classList.remove('on');});b.classList.add('on');});});
document.getElementById('fdSend').addEventListener('click',function(){document.getElementById('fdOk').hidden=false;});

/* recently viewed */
function renderRecent(){var s=document.getElementById('recent');if(!recent.length){s.hidden=true;return;}s.hidden=false;document.getElementById('recentGrid').innerHTML=recent.map(function(id){return byId[id]?cardHTML(byId[id]):'';}).join('');}

render();syncWish();renderRecent();
if(location.hash.indexOf('#p=')===0){var h=location.hash.slice(3);if(byId[h]){setTimeout(function(){document.getElementById('catalogus').scrollIntoView();openProduct(h);},50);}}

var burger=document.getElementById('burger'),navEl=document.querySelector('.nav');
burger.addEventListener('click',function(){var o=navEl.classList.toggle('open');burger.setAttribute('aria-expanded',o?'true':'false');});
navEl.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){navEl.classList.remove('open');burger.setAttribute('aria-expanded','false');});});
document.getElementById('noticeClose').addEventListener('click',function(){document.getElementById('notice').classList.add('hide');});
// highlight active nav item
var links=document.querySelectorAll('.nav a'),map={};
links.forEach(function(a){var s=document.querySelector(a.getAttribute('href'));if(s)map[s.id]=a;});
if('IntersectionObserver' in window){
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){links.forEach(function(a){a.classList.remove('active');});map[e.target.id].classList.add('active');}});},{rootMargin:'-40% 0px -55% 0px'});
  Object.keys(map).forEach(function(id){io.observe(document.getElementById(id));});
}

/* language toggle */
var langBtn=document.getElementById('langBtn');
function applyLang(l){
  lang=l;document.documentElement.lang=l;
  document.querySelectorAll('.i18n').forEach(function(el){
    var v=l==='en'?el.dataset.en:null, vh=l==='en'?el.dataset.enHtml:null;
    if(vh!=null){ if(!el.dataset.nlHtml)el.dataset.nlHtml=el.innerHTML; el.innerHTML=vh; }
    else if(v!=null){ if(!el.dataset.nl)el.dataset.nl=el.textContent; el.textContent=v; }
    else if(el.dataset.nlHtml!=null){ el.innerHTML=el.dataset.nlHtml; }
    else if(el.dataset.nl!=null){ el.textContent=el.dataset.nl; }
  });
  langBtn.textContent=l==='en'?'NL':'EN';
  render();syncWish();renderRecent();
  if(pdId)openProduct(pdId);
}
langBtn.addEventListener('click',function(){applyLang(lang==='en'?'nl':'en');lsSet('rj_lang',lang);});
var savedLang=ls('rj_lang','nl');
if(savedLang==='en')applyLang('en');

/* cookie notice */
var cookiebar=document.getElementById('cookiebar');
var consent=ls('rj_consent',null);
if(!consent){setTimeout(function(){cookiebar.classList.add('show');},600);}
else{document.getElementById('ccPref').checked=!!consent.pref;document.getElementById('ccStat').checked=!!consent.stat;document.getElementById('ccMkt').checked=!!consent.mkt;}
function saveConsent(c){lsSet('rj_consent',c);cookiebar.classList.remove('show');document.getElementById('cd').classList.remove('show');document.getElementById('cd').setAttribute('aria-hidden','true');document.body.classList.remove('open');document.getElementById('scrim').classList.remove('open');}
document.getElementById('cookieAcceptAll').addEventListener('click',function(){document.getElementById('ccPref').checked=true;document.getElementById('ccStat').checked=true;document.getElementById('ccMkt').checked=true;saveConsent({pref:true,stat:true,mkt:true});});
document.getElementById('cookieNecessaryOnly').addEventListener('click',function(){document.getElementById('ccPref').checked=false;document.getElementById('ccStat').checked=false;document.getElementById('ccMkt').checked=false;saveConsent({pref:false,stat:false,mkt:false});});
document.getElementById('cookieCustomize').addEventListener('click',function(){open('cd');});
document.getElementById('cdClose').addEventListener('click',function(){closeAll();});
document.getElementById('cdSave').addEventListener('click',function(){saveConsent({pref:document.getElementById('ccPref').checked,stat:document.getElementById('ccStat').checked,mkt:document.getElementById('ccMkt').checked});});
